def set_coords(apps, schema_editor):
    import re

    Building = apps.get_model("core", "Building")
    seen = {}
    for b in Building.objects.all():
        text = (b.title + " " + (b.description or "")).lower()
        coords, prec = None, "viloyat"
        for rx, c, p in DISTRICTS:
            if re.search(rx, text):
                coords, prec = c, p
                break
        if not coords:
            region = b.region.name if b.region_id else "Toshkent shahri"
            coords = REGIONS.get(region, REGIONS["Toshkent shahri"])
        # bir nuqtaga tushgan markerlar ustma-ust chiqmasligi uchun ozgina siljitish
        n = seen.get(coords, 0)
        seen[coords] = n + 1
        lat = coords[0] + 0.004 * n
        lng = coords[1] + 0.005 * n
        b.latitude = Decimal(str(round(lat, 6)))
        b.longitude = Decimal(str(round(lng, 6)))
        b.location_precision = prec
        b.save(update_fields=["latitude", "longitude", "location_precision"])



